import React, { useEffect, useState } from "react";
import axios from "axios";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import "./manageUserAccounts.css";

function AdminUserManagement() {
  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [viewStudents, setViewStudents] = useState(false);
  const [viewSupervisors, setViewSupervisors] = useState(false);
  const [viewEvaluators, setViewEvaluators] = useState(false);

  useEffect(() => {
    axios.get("http://localhost:5000/api/user/users").then((response) => {
      const users = response.data;
      const std = users.filter((user) => user.role === "student");
      const spv = users.filter((user) => user.role === "supervisor");
      const evl = users.filter((user) => user.role === "evaluator");

      setStudents(std);
      setSupervisors(spv);
      setEvaluators(evl);
    });
  }, []);

  const handleEdit = (id, role) => {
    console.log(`Edit ${role} with ID: ${id}`);
    // Navigate or open modal
  };

  const handleResetPassword = (id, role) => {
    console.log(`Reset password for ${role} with ID: ${id}`);
    // API call to reset password
  };

  const handleDelete = (id, role) => {
    console.log(`Delete ${role} with ID: ${id}`);
    // API call to delete user
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>User Management</h1>
          <div>
            <button onClick={() => setViewStudents(!viewStudents)}>
              Toggle Students
            </button>
            <button onClick={() => setViewSupervisors(!viewSupervisors)}>
              Toggle Supervisors
            </button>
            <button onClick={() => setViewEvaluators(!viewEvaluators)}>
              Toggle Evaluators
            </button>
          </div>

          {/* Students */}
          {viewStudents && students.length > 0 && (
            <div className="student-table">
              <h2>Student List</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Registration Number</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((student) => (
                    <tr key={student.regNo}>
                      <td>{student.name}</td>
                      <td>{student.email}</td>
                      <td>{student.role}</td>
                      <td>{student.registrationNumber}</td>
                      <td>
                        <button onClick={() => handleEdit(student.regNo, "student")}>Edit</button>
                        <button onClick={() => handleResetPassword(student.regNo, "student")}>Reset Password</button>
                        <button onClick={() => handleDelete(student.regNo, "student")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Supervisors */}
          {viewSupervisors && supervisors.length > 0 && (
            <div className="supervisor-table">
              <h2>Supervisor List</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {supervisors.map((supervisor) => (
                    <tr key={supervisor.email}>
                      <td>{supervisor.name}</td>
                      <td>{supervisor.email}</td>
                      <td>{supervisor.role}</td>
                      <td>
                        <button onClick={() => handleEdit(supervisor.email, "supervisor")}>Edit</button>
                        <button onClick={() => handleResetPassword(supervisor.email, "supervisor")}>Reset Password</button>
                        <button onClick={() => handleDelete(supervisor.email, "supervisor")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Evaluators */}
          {viewEvaluators && evaluators.length > 0 && (
            <div className="evaluator-table">
              <h2>Evaluator List</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {evaluators.map((evaluator) => (
                    <tr key={evaluator.email}>
                      <td>{evaluator.name}</td>
                      <td>{evaluator.email}</td>
                      <td>{evaluator.role}</td>
                      <td>
                        <button onClick={() => handleEdit(evaluator.email, "evaluator")}>Edit</button>
                        <button onClick={() => handleResetPassword(evaluator.email, "evaluator")}>Reset Password</button>
                        <button onClick={() => handleDelete(evaluator.email, "evaluator")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default AdminUserManagement;
